package history
import("clean-code/internal/approval";"crypto/sha256";"encoding/hex";"encoding/json";"errors";"io";"os";"sort";"strings")
type Signal struct{Name string `json:"name"`;Value float64 `json:"value"`;Scale string `json:"scale"`;Provenance string `json:"provenance"`}
type Content struct{Repository string `json:"repository"`;Revision string `json:"revision"`;CreatedAt string `json:"created_at"`;Signals []Signal `json:"signals"`}
type Receipt struct{SchemaVersion string `json:"schema_version"`;Digest string `json:"digest"`;Content Content `json:"content"`}
type Point struct{Revision string `json:"revision"`;CreatedAt string `json:"created_at"`;Value float64 `json:"value"`};type Trend struct{Name string `json:"name"`;Scale string `json:"scale"`;Provenance string `json:"provenance"`;Points []Point `json:"points"`};type Report struct{SchemaVersion string `json:"schema_version"`;Receipts []Receipt `json:"receipts"`;Trends []Trend `json:"trends"`}
type ApprovalManifest struct{SchemaVersion string `json:"schema_version"`;Repository string `json:"repository"`;ReceiptDigests []string `json:"receipt_digests"`}
func ParseApproval(body []byte)(ApprovalManifest,error){var m ApprovalManifest;d:=json.NewDecoder(strings.NewReader(string(body)));d.DisallowUnknownFields();if err:=d.Decode(&m);err!=nil{return m,err};if m.SchemaVersion!="1.0.0"||m.Repository==""||len(m.ReceiptDigests)==0{return m,errors.New("history approval is incomplete")};return m,nil}
func VerifyApproval(body,sig,key []byte,m ApprovalManifest,receipts []Receipt)error{if err:=approval.VerifyBytes(body,sig,key);err!=nil{return err};if len(m.ReceiptDigests)!=len(receipts){return errors.New("history approval receipt set differs")};for i,r:=range receipts{if m.ReceiptDigests[i]!=r.Digest||m.Repository!=r.Content.Repository{return errors.New("history receipt is not approved")}};return nil}
func ParseReceipt(body []byte)(Receipt,error){d:=json.NewDecoder(strings.NewReader(string(body)));d.DisallowUnknownFields();var r Receipt;if err:=d.Decode(&r);err!=nil{return r,err};return r,nil}
func Load(path string)(Receipt,error){f,err:=os.Open(path);if err!=nil{return Receipt{},err};defer f.Close();d:=json.NewDecoder(f);d.DisallowUnknownFields();var r Receipt;if err:=d.Decode(&r);err!=nil{return r,err};var x any;if err:=d.Decode(&x);!errors.Is(err,io.EOF){return r,errors.New("unexpected trailing JSON")};return r,nil}
func Digest(c Content)string{body,_:=json.Marshal(c);sum:=sha256.Sum256(body);return hex.EncodeToString(sum[:])}
func Build(receipts []Receipt)(Report,error){seen:=map[string]bool{};for _,r:=range receipts{c:=r.Content;if r.SchemaVersion!="1.0.0"||r.Digest!=Digest(c)||c.Repository==""||c.Revision==""||c.CreatedAt==""||seen[r.Digest]{return Report{},errors.New("receipt is invalid, duplicated, or tampered")};seen[r.Digest]=true;for _,s:=range c.Signals{if s.Name==""||s.Scale==""||s.Provenance==""{return Report{},errors.New("signal metadata is incomplete")}}};sort.Slice(receipts,func(i,j int)bool{a,b:=receipts[i].Content,receipts[j].Content;if a.CreatedAt==b.CreatedAt{return a.Revision<b.Revision};return a.CreatedAt<b.CreatedAt});trendMap:=map[string]*Trend{};for _,r:=range receipts{for _,s:=range r.Content.Signals{k:=s.Name+"\x00"+s.Scale+"\x00"+s.Provenance;if trendMap[k]==nil{trendMap[k]=&Trend{Name:s.Name,Scale:s.Scale,Provenance:s.Provenance}};trendMap[k].Points=append(trendMap[k].Points,Point{Revision:r.Content.Revision,CreatedAt:r.Content.CreatedAt,Value:s.Value})}};trends:=[]Trend{};for _,t:=range trendMap{trends=append(trends,*t)};sort.Slice(trends,func(i,j int)bool{if trends[i].Name==trends[j].Name{return trends[i].Provenance<trends[j].Provenance};return trends[i].Name<trends[j].Name});return Report{SchemaVersion:"1.0.0",Receipts:receipts,Trends:trends},nil}
